import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Installation","description":"Install GameFilter XDP from the release package — prerequisites, interactive install steps, post-install verification, troubleshooting, and uninstall.","frontmatter":{"title":"Installation","description":"Install GameFilter XDP from the release package — prerequisites, interactive install steps, post-install verification, troubleshooting, and uninstall."},"headers":[],"relativePath":"gamefilter-xdp/getting-started/installation.md","filePath":"gamefilter-xdp/getting-started/installation.md","lastUpdated":1787468851000}'),n={name:"gamefilter-xdp/getting-started/installation.md"};function l(o,e,r,d,p,h){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><blockquote><p><strong>Get GameFilter XDP validating game traffic in a few minutes.</strong> The release package ships pre-built binaries — no Rust toolchain, no build tools, nothing else to install. Root and a 5.15+ kernel with BTF are all you need.</p></blockquote><nav class="table-of-contents"><ul><li><a href="#prerequisites">Prerequisites</a></li><li><a href="#install-steps">Install Steps</a><ul><li><a href="#step-1-3-—-private-interface">Step 1/3 — Private interface</a></li><li><a href="#step-2-3-—-filters-default-action">Step 2/3 — Filters &amp; default action</a></li><li><a href="#step-3-3-—-management-api">Step 3/3 — Management API</a></li><li><a href="#what-gets-installed">What gets installed</a></li></ul></li><li><a href="#verification">Verification</a></li><li><a href="#troubleshooting">Troubleshooting</a><ul><li><a href="#the-loader-fails-with-a-verifier-or-load-error">The loader fails with a verifier or load error</a></li><li><a href="#legit-players-are-being-dropped-false-drops">Legit players are being dropped (false drops)</a></li><li><a href="#locked-out-after-enabling-default-action-drop">Locked out after enabling default_action: drop</a></li><li><a href="#gamefilter-status-says-not-loaded">gamefilter status says &quot;NOT loaded&quot;</a></li></ul></li><li><a href="#uninstall">Uninstall</a></li></ul></nav><hr><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Minimum</th><th>Check</th></tr></thead><tbody><tr><td>Kernel</td><td>Linux <strong>5.15+</strong></td><td><code>uname -r</code></td></tr><tr><td>Kernel BTF</td><td><code>CONFIG_DEBUG_INFO_BTF=y</code></td><td><code>ls /sys/kernel/btf/vmlinux</code></td></tr><tr><td>Privileges</td><td>root</td><td><code>id -u</code> → <code>0</code></td></tr><tr><td>Topology</td><td>A <strong>private NIC</strong> between your edge firewall and the game servers</td><td><code>ip link</code></td></tr></tbody></table><p>The release package has <strong>no other dependencies</strong> — the XDP object (<code>gamefilter-ebpf.o</code>) and the userspace binary (<code>gamefilter</code>) are pre-built.</p><div class="warning custom-block"><p class="custom-block-title">BTF is not optional</p><p>The eBPF program is a CO-RE object and requires kernel BTF. If <code>/sys/kernel/btf/vmlinux</code> does not exist, the installer stops immediately. Virtually all modern distro kernels (Ubuntu 22.04+, Debian 12+, Fedora, Arch, Rocky/Alma 9+) ship BTF enabled.</p></div><div class="danger custom-block"><p class="custom-block-title">GameFilter goes on the PRIVATE interface</p><p>GameFilter is designed to sit <strong>behind</strong> your edge firewall, on the NIC that faces your game servers — with <code>default_action: drop</code>, anything that matches no filter is dropped. If you attach it to the interface you manage the machine through without an <code>ssh</code> filter or a whitelist entry for your admin IP, you can lock yourself out.</p></div><hr><h2 id="install-steps" tabindex="-1">Install Steps <a class="header-anchor" href="#install-steps" aria-label="Permalink to &quot;Install Steps&quot;">​</a></h2><p>Extract the release package and run the installer as root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gamefilter-xdp-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.tar.gz</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # or unzip the release zip</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gamefilter-xdp-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./install.sh</span></span></code></pre></div><p>The installer works on Debian/Ubuntu (apt), Fedora/RHEL (dnf/yum), Arch (pacman), Alpine (apk), and openSUSE (zypper) — with a release package it needs none of them, but it will happily build from source instead if you run it from a source checkout (nightly Rust + <code>rust-src</code> + <code>bpf-linker</code> required in that case).</p><p>After pre-flight checks (kernel version, BTF), it asks three questions:</p><h3 id="step-1-3-—-private-interface" tabindex="-1">Step 1/3 — Private interface <a class="header-anchor" href="#step-1-3-—-private-interface" aria-label="Permalink to &quot;Step 1/3 — Private interface&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[*] Step 1/3 — Private interface</span></span>
<span class="line"><span>    GameFilter sits on the PRIVATE NIC (between the edge firewall and</span></span>
<span class="line"><span>    your game servers), not the public one.</span></span>
<span class="line"><span>    Available interfaces:</span></span>
<span class="line"><span>      ▸ eth0             (up)</span></span>
<span class="line"><span>      ▸ eth1             (up)</span></span>
<span class="line"><span>[?] Interface to filter (the private one) [eth1]:</span></span></code></pre></div><p>Auto-detected from your default route — <strong>check that the guess is actually your private NIC</strong> before pressing Enter.</p><h3 id="step-2-3-—-filters-default-action" tabindex="-1">Step 2/3 — Filters &amp; default action <a class="header-anchor" href="#step-2-3-—-filters-default-action" aria-label="Permalink to &quot;Step 2/3 — Filters &amp; default action&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[!] default_action: drop blocks EVERYTHING that matches no filter.</span></span>
<span class="line"><span>[!] Make sure the ssh filter (or your admin IP in whitelist) is in place</span></span>
<span class="line"><span>[!] if you manage this machine through the filtered interface.</span></span>
<span class="line"><span>[?] Keep default_action: drop (recommended for a dedicated game NIC)? [Y/n]:</span></span></code></pre></div><p>The shipped config already includes filters for <code>mc-java</code> (25565), <code>mc-bedrock</code> (19132), <code>geyser</code> (19133), <code>fivem</code> (30120), <code>source-engine</code> (27015-27050), and <code>ssh</code> (22). <code>drop</code> is the recommended posture for a dedicated game NIC; choose <code>pass</code> if other services share the interface.</p><h3 id="step-3-3-—-management-api" tabindex="-1">Step 3/3 — Management API <a class="header-anchor" href="#step-3-3-—-management-api" aria-label="Permalink to &quot;Step 3/3 — Management API&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[?] Enable the HTTP management API? [Y/n]:</span></span>
<span class="line"><span>[?] Listen address (127.0.0.1 = local only) [127.0.0.1:9300]:</span></span></code></pre></div><p>The installer generates a random API key (<code>gf_</code> + 32 hex chars), writes it into the config, and prints it at the end. Everything — stats, lists, config — goes through this API (no TUI by design), so keep it enabled unless you have a reason not to. Keep the listen address on <code>127.0.0.1</code> unless you also set <a href="./../configuration/reference#api-whitelist"><code>api.whitelist</code></a>.</p><p>Finally it asks whether to enable and start the systemd services (<code>gamefilter-loader.service</code>, and <code>gamefilter-api.service</code> if the API is on).</p><h3 id="what-gets-installed" tabindex="-1">What gets installed <a class="header-anchor" href="#what-gets-installed" aria-label="Permalink to &quot;What gets installed&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Path</th><th>Contents</th></tr></thead><tbody><tr><td><code>/opt/gamefilter/gamefilter</code></td><td>Userspace binary (symlinked to <code>/usr/local/bin/gamefilter</code>)</td></tr><tr><td><code>/opt/gamefilter/gamefilter-ebpf.o</code></td><td>Pre-built XDP object</td></tr><tr><td><code>/etc/gamefilter/gamefilter.yaml</code></td><td>Configuration (<code>chmod 600</code>; an existing file is backed up to <code>.bak</code>)</td></tr><tr><td><code>/var/lib/gamefilter/state.json</code></td><td>Load-time state snapshot (interface, mode, filter table)</td></tr><tr><td><code>/etc/systemd/system/gamefilter-loader.service</code></td><td>Oneshot unit: <code>gamefilter load</code> / <code>unload</code></td></tr><tr><td><code>/etc/systemd/system/gamefilter-api.service</code></td><td>Resident daemon: HTTP API + OpenShield sync</td></tr></tbody></table><hr><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gamefilter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GameFilter XDP is loaded.</span></span>
<span class="line"><span>  Interface: eth1 (native)</span></span>
<span class="line"><span>  Packets: 128412 passed, 9033 dropped | validated ok 4210 fail 8801 | admitted 120244 | banned 17</span></span>
<span class="line"><span>  [ 0] mc-java        tcp ports=25565              pass=52100 drop=1200</span></span>
<span class="line"><span>  [ 1] mc-bedrock     udp ports=19132              pass=61302 drop=7715</span></span>
<span class="line"><span>  [ 2] source-engine  udp ports=27015-27050        pass=15010 drop=118</span></span></code></pre></div><p>Check the systemd units and the API:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gamefilter-loader.service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gamefilter-api.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gamefilter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # prints the API URL + key and a ready-to-paste curl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer &lt;key&gt;&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:9300/health</span></span></code></pre></div><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;generated_at&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1755931200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;api_uptime_seconds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">312</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;loaded&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>A quick end-to-end proof: ping a Bedrock filter port with a crafted RakNet unconnected ping and watch <code>validated_ok</code> increment, then send random bytes and watch <code>validated_fail</code> (and eventually <code>banned</code>) increment.</p><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="the-loader-fails-with-a-verifier-or-load-error" tabindex="-1">The loader fails with a verifier or load error <a class="header-anchor" href="#the-loader-fails-with-a-verifier-or-load-error" aria-label="Permalink to &quot;The loader fails with a verifier or load error&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gamefilter-loader.service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gamefilter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> load</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # run in the foreground for the full error</span></span></code></pre></div><ul><li><strong><code>Kernel BTF not found</code></strong> — your kernel lacks <code>CONFIG_DEBUG_INFO_BTF</code>. Switch to a distro/mainline kernel that ships it.</li><li><strong>Verifier rejection on load</strong> — the object targets kernel 5.15+; report the full log if a supported kernel rejects it.</li><li><strong>Native attach failed</strong> — the loader automatically falls back to generic (SKB) mode; <code>gamefilter status</code> shows the mode next to the interface. Generic mode is slower but fully functional.</li></ul><h3 id="legit-players-are-being-dropped-false-drops" tabindex="-1">Legit players are being dropped (false drops) <a class="header-anchor" href="#legit-players-are-being-dropped-false-drops" aria-label="Permalink to &quot;Legit players are being dropped (false drops)&quot;">​</a></h3><ol><li>Find the offending filter in <code>sudo gamefilter status</code> (its <code>validated_fail</code> counter climbs while players connect).</li><li>Check the size bounds against the project&#39;s <code>docs/protocol-research.md</code> — the most common cause is a <code>max_size</code> that is too tight for your setup (e.g. modded servers, proxies in front).</li><li>Widen the filter: raise <code>max_size</code>, lower <code>min_size</code>, and if the validator itself is too strict for your traffic (the <code>fivem</code> ENet CONNECT check is UNVERIFIED upstream), switch that port to <code>udp_generic</code> and keep the size bounds tight.</li><li><code>sudo gamefilter reload</code> to hot-apply — no detach, no protection gap.</li></ol><div class="tip custom-block"><p class="custom-block-title">Soften the punishment while you tune</p><p>Set <code>ban_sec: 0</code> (never ban, just drop) or raise <code>max_failures</code> on the filter you are tuning, so a mis-tuned validator drops individual packets instead of temp-banning real players.</p></div><h3 id="locked-out-after-enabling-default-action-drop" tabindex="-1">Locked out after enabling <code>default_action: drop</code> <a class="header-anchor" href="#locked-out-after-enabling-default-action-drop" aria-label="Permalink to &quot;Locked out after enabling \`default_action: drop\`&quot;">​</a></h3><p>Attach over a console/IPMI, then either add your admin IP (<code>sudo gamefilter whitelist add &lt;your-ip&gt;</code> and keep it in the config <code>whitelist:</code> so it survives reloads) or flip <code>default_action: pass</code> and <code>sudo gamefilter reload</code>.</p><h3 id="gamefilter-status-says-not-loaded" tabindex="-1"><code>gamefilter status</code> says &quot;NOT loaded&quot; <a class="header-anchor" href="#gamefilter-status-says-not-loaded" aria-label="Permalink to &quot;\`gamefilter status\` says &quot;NOT loaded&quot;&quot;">​</a></h3><p>The pinned link at <code>/sys/fs/bpf/gamefilter/link</code> is missing — the loader service is down or the attach failed. Check <code>journalctl -u gamefilter-loader.service</code>, then <code>sudo gamefilter load</code>.</p><hr><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./uninstall.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # stops services, detaches XDP, removes binaries</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./uninstall.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --purge</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # also removes /etc/gamefilter and /var/lib/gamefilter</span></span></code></pre></div><p>The uninstaller disables and removes both systemd units, unloads the XDP program (removing <code>/sys/fs/bpf/gamefilter</code> and the state file), and deletes <code>/opt/gamefilter</code> and <code>/usr/local/bin/gamefilter</code>. Without <code>--purge</code>, your config and state are kept for a later reinstall.</p>`,51)])])}const k=a(n,[["render",l]]);export{u as __pageData,k as default};
